//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_NO_COMT = "위원회심사결과 내역이 없습니다. 새로 추가하시겠습니까?";
scwin.MSG_NO_FILE = "기존첨부파일이 있습니다";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyLstBzProcsNo = "", scwin.strKeyIsurCd = "";
scwin.contnId;
scwin.file_flag = "N";
scwin.vScrenID = "ULDSTF05010.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_ShowCalendar = function(o) {
    if ((o != undefined) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
};
scwin.fn_getUserId = function() {
    return js_emp_no;
};
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "COMITE_INVSTG_RSLT_CD",
        cnm: "cmb_ComiteInvstgRsltCd"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='COMITE_INVSTG_RSLT_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};


// search function begin
scwin.fn_searchReqInf = function() {
    var uri = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchCmtdelibReqInf" + "&inputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" + "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" + "&BZ_PROCS_NO=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
    dts_ReqInf.DataID = encodeURI(uri);
    dts_ReqInf.reset();
};
scwin.fn_search = function() {
    // 발행기관코드가 키값이다.
    var uri = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCmtdelib" + "&inputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" + "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" + "&ISUR_CD=" + scwin.strKeyIsurCd;
    dts_Cmt.DataID = encodeURI(uri);
    dts_Cmt.reset();
};

// search function end
scwin.fn_save = function(jobType) {
    {
        /*
        var s = "";
        for (i = 1; i <= dts_ReqInf.CountColumn; i++) { s = s + "\n" +  dts_ReqInf.ColumnID(i) + "," + dts_ReqInf.ColumnString(1, i); }
        log.Text = log.Text + "\n" + s + "\n" + dts_ReqInf.Text;

        s = "";
        for (i = 1; i <= dts_Cmt.CountColumn; i++) { s = s + "\n" +  dts_Cmt.ColumnID(i) + "," + dts_Cmt.ColumnString(1, i); }
        log.Text = log.Text + "\n" + s + "\n" + dts_Cmt.Text;
        */
    }
    if (js_dep_cd.substring(0, 2) !== '33') {
        //코스닥 심사팀
        $c.win.alert("해당 부서만 접수가 가능합니다.");
        return;
    }

    //2009.05.12 위원회일/철회일 필수 체크
    if (med_ComiteDd.getValue() == "") {
        $c.win.alert("위원회일/철회일을 입력하여 주세요");
        med_ComiteDd.focus();
        return false;
    }
    var check = scwin.fn_fileYnCheck();
    var vScrenProcTpCd;
    if (jobType == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        // dts_ReqInf의 UseChangeInfo를 false로 지정하여 무조건 insert상태로 서버로 전송됨.
        dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", scwin.fn_getUserId());
        tr_Save.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveCmtdelib";
        tr_Save.KeyName = "toinb_dataid4";
        tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf,I:pInpCmt=dts_Cmt ,I:pFile=dts_fileList)";
        tr_Save.Post();
    } else if (!$c.cp.isModified(dts_Cmt) && !$c.cp.isModified(dts_ReqInf) && check == "Y") {
        scwin.fn_fileInsert();
    } else {
        $c.win.alert(scwin.MGS_NO_UPDT);
    }
};


//파일첨부 삭제 여부
scwin.fn_fileYnCheck = function() {
    for (i = 1; i <= dts_fileList.getTotalRow(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") != "") {
            scwin.file_flag = "Y";
        }
    }
    return scwin.file_flag;
};


//첨부파일 저장
scwin.fn_fileInsert = function() {
    if ($c.cp.isModified(dts_fileList)) {
        //alert(dts_fileList.Text);
        tr_File.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveFiledelib&BZ_PROCS_NO=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
        tr_File.KeyValue = "JSP(I:pFile=dts_fileList)";
        tr_File.Post();
    }
};



//첨부파일 조회
scwin.fn_fileSearch = function() {
    var url = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchFiledelib" + "&inputMessageId=PRELISTING_KOSDAQ_DATA_INOUT" + "&outputMessageId=PRELISTING_KOSDAQ_DATA_INOUT" + "&BZ_PROCS_NO="++dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
    dts_fileList.DataID = encodeURI(url);
    dts_fileList.reset();
};

//
scwin.fn_txbLoad = function() {
    var txbArr = [txb_file_name, txb_file_name2, txb_file_name3, txb_file_name4, txb_file_name5];
    for (var i = 0; i < txbArr.length; i++) {
        txbArr[i].setValue("");
    }
};


//첨부파일 읽기 
scwin.fn_read = function() {
    scwin.fn_txbLoad();
    tr_ReadFile.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readFiledelib&BZ_PROCS_NO=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
    tr_ReadFile.KeyValue = "JSP(O:pOutput=dts_fileList)";
    tr_ReadFile.Post();
};


